      practice: [mc('«Do you speak English?» =', ['¿Haces hablas inglés?', '¿Hablas inglés?'], 1, 'Spanish has no auxiliary «do».'), mc('Add a tag: «Es caro, ___»', ['¿no?', '¿sí no?'], 0), bd(['¿vive', 'aquí', 'tu', 'hermana?'], 'vive aquí tu hermana', 'Does your sister live here?'), fl('No sé ___ vive. (where — indirect)', ['dónde', 'donde']), tr('Are you tired?', ['¿estás cansada?', '¿estás cansado?', 'estas cansada', 'estas cansado', 'estás cansada', 'estás cansado']), tr('You are Kait, right?', ['eres kait, ¿verdad?', 'eres kait, ¿no?', 'eres kait verdad', 'eres kait no'])],
      quiz: [mc('Where does ¿ go in «Bueno, ¿vienes?»', ['before Bueno', 'before vienes'], 1), mc('Which is a correct question?', ['¿Usted es de aquí?', '¿Hace usted es de aquí?'], 0), mc('«¿vale?» at the end means…', ['OK?', 'how much?'], 0), mc('Indirect: «I don’t know what he wants» =', ['No sé que quiere.', 'No sé qué quiere.'], 1), mc('Yes/no questions in Spanish…', ['need «do»', 'use intonation and ¿?'], 1)]
