      quiz: [mc('Where does «no» go with a pronoun?', ['No lo quiero.', 'Lo no quiero.'], 0), mc('«Nobody knows» =', ['No nadie sabe.', 'Nadie sabe.'], 1), mc('Double negatives in Spanish are…', ['wrong', 'normal and correct'], 1), mc('«I don’t see anything» =', ['No veo nada.', 'Veo nada.'], 0), mc('«No, I don’t» answer:', ['No, no.', 'No, yo no.', 'Both are possible'], 2)]
