      quiz: [mc('«the oldest in the family» (person):', ['el mayor de la familia', 'el mayor en la familia'], 0), mc('-ísimo of «largo»:', ['larguísimo', 'largísimo'], 0), mc('«the worst» =', ['el más malo', 'el peor'], 1), mc('«Es la ___ amiga»', ['mejor', 'más buena'], 0), mc('Absolute superlative means…', ['the most of a group', 'extremely'], 1)]
