      quiz: [mc('«a lot of people» =', ['muchas gentes', 'mucha gente'], 1), mc('«I sleep little» =', ['Duermo poco.', 'Duermo un poco.'], 0), mc('Which never changes form?', ['mucho', 'muy'], 1), mc('«quite cheap» =', ['bastante barato', 'bastantes barato'], 0), mc('«too much salt» =', ['demasiado sal', 'demasiada sal'], 1)]
